static void mvs_free(struct mvs_info *mvi)
{
	struct mvs_work_queue *mwq;
	if (mvi->shost)
		scsi_host_put(mvi->shost);
	list_for_each_entry(mwq, &mvi->wq_list, entry)
		cancel_delayed_work_sync(&mwq->work_q);
	kfree(mvi->rsvd_tags);
	kfree(mvi);
}
